pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(c));
        // A helper that always returns true for transferFrom to simulate a successful external call
        SuccessCallee callee = new SuccessCallee();
        address target = address(callee);
        // Use vm.prank to set msg.sender; use the callee as the external token
        vm.prank(from);
        bool returned = c.transfer(from, target, _tos, v);
        assertTrue(returned);
    }
}

contract SuccessCallee {
    fallback() external payable returns (bool) {
        return true;
    }
}

