// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(address(c) != caddress);
        vm.assume(caddress != address(this));
        // Deploy adversarial helper that will cause the external call to fail
        Reverter reverter = new Reverter();
        // Construct array with one element being the adversarial helper and rest fuzzed addresses
        address[] memory tos = new address[](_tos.length);
        for (uint i = 0; i < _tos.length; i++) {
            if (i == 0) {
                tos[i] = address(reverter);
            } else {
                tos[i] = _tos[i];
            }
        }
        bool ok;
        try c.transfer(from, caddress, tos, v) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference C must always revert (because at least one external call to reverter fails),
        // while the mutant returns true without reverting.
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

