        vm.assume(_tos.length > 0);
        vm.assume(_tos.length < 100);
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        (bool ok, ) = caddress.call(abi.encodeWithSelector(id, from, address(0), uint256(0)));
        // ensure caddress has the expected function selector to avoid revert from unknown selector
        bool success;
        try c.transfer(from, caddress, _tos, v) returns (bool) {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success);
    }
}
